{"version":3,"file":"console-main.jsdbx","sources":["../../src/client/services/ExportConfigService.js","../../src/client/components/ConsoleLanding.jsx","../../src/client/components/ExportDefinitionWizard.jsx","../../src/client/components/FieldMappingManager.jsx","../../src/client/components/RelatedSourceManager.jsx","../../src/client/components/ExportTester.jsx","../../src/client/components/ConsoleLanding.css","../../src/client/ExportConsole.css","../../src/client/console-main.jsx","../../src/client/ExportConsole.jsx"],"sourcesContent":["export class ExportConfigService {
  constructor() {
    this.scopeName = 'x_271493_dynamic_c';
    this.tables = {
      exportDefinition: `${this.scopeName}_export_definition`,
      exportMapping: `${this.scopeName}_export_mapping`,
      csvRelatedSource: `${this.scopeName}_csv_related_source`,
      exportLog: `${this.scopeName}_export_log`
    };
  }

  // Utility methods for field extraction
  extractValue(field) {
    return typeof field === 'object' ? field.value : field;
  }

  extractDisplayValue(field) {
    return typeof field === 'object' ? field.display_value : field;
  }

  // Export Definitions
  async getExportDefinitions() {
    return this._fetchTableData(this.tables.exportDefinition, {
      sysparm_display_value: 'all',
      sysparm_order_by: '-sys_updated_on'
    });
  }

  async getExportDefinition(sysId) {
    const data = await this._fetchTableData(this.tables.exportDefinition, {
      sysparm_display_value: 'all',
      sysparm_query: `sys_id=${sysId}`
    });
    return data.length > 0 ? data[0] : null;
  }

  async createExportDefinition(definitionData) {
    return this._postTableData(this.tables.exportDefinition, definitionData);
  }

  async updateExportDefinition(sysId, definitionData) {
    return this._putTableData(this.tables.exportDefinition, sysId, definitionData);
  }

  async deleteExportDefinition(sysId) {
    return this._deleteTableData(this.tables.exportDefinition, sysId);
  }

  // Field Mappings
  async getFieldMappings(definitionId) {
    return this._fetchTableData(this.tables.exportMapping, {
      sysparm_display_value: 'all',
      sysparm_query: `export_definition=${definitionId}`,
      sysparm_order_by: 'order_number'
    });
  }

  async createFieldMapping(mappingData) {
    return this._postTableData(this.tables.exportMapping, mappingData);
  }

  async updateFieldMapping(sysId, mappingData) {
    return this._putTableData(this.tables.exportMapping, sysId, mappingData);
  }

  async deleteFieldMapping(sysId) {
    return this._deleteTableData(this.tables.exportMapping, sysId);
  }

  // Related Sources
  async getRelatedSources(definitionId) {
    return this._fetchTableData(this.tables.csvRelatedSource, {
      sysparm_display_value: 'all',
      sysparm_query: `export_definition=${definitionId}`,
      sysparm_order_by: 'alias'
    });
  }

  async createRelatedSource(sourceData) {
    return this._postTableData(this.tables.csvRelatedSource, sourceData);
  }

  async updateRelatedSource(sysId, sourceData) {
    return this._putTableData(this.tables.csvRelatedSource, sysId, sourceData);
  }

  async deleteRelatedSource(sysId) {
    return this._deleteTableData(this.tables.csvRelatedSource, sysId);
  }

  // Test Export - calls server-side Script Include
  async testExport(definitionId, recordIds = [], previewOnly = true) {
    try {
      const response = await fetch('/api/now/table/sys_script_include', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-UserToken': window.g_ck
        },
        body: JSON.stringify({
          name: 'CSVExportTestRunner',
          script: `
            var engine = new CSVExportEngine();
            var result = engine.generate('${definitionId}');

            // For preview mode, limit to first 10 rows
            if (${previewOnly} && result.success && result.csvContent) {
              var lines = result.csvContent.split('\\n');
              result.previewContent = lines.slice(0, 11).join('\\n'); // Header + 10 rows
              result.totalLines = lines.length - 1; // Exclude header
            }

            gs.print(JSON.stringify(result));
          `
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      return JSON.parse(data.result || '{}');
    } catch (error) {
      console.error('Test export error:', error);
      throw new Error('Failed to test export: ' + error.message);
    }
  }

  // Table schema operations
  async getTableList() {
    try {
      const tables = await this._fetchTableData('sys_db_object', {
        sysparm_fields: 'name,label,super_class',
        sysparm_query: 'nameNOT LIKEsys_%^nameNOT LIKEts_%',
        sysparm_order_by: 'label',
        sysparm_limit: 1000
      });

      return tables.map(table => ({
        name: this.extractValue(table.name),
        label: this.extractDisplayValue(table.label) || this.extractValue(table.name)
      }));
    } catch (error) {
      console.error('Error fetching table list:', error);
      return [];
    }
  }

  async getTableFields(tableName) {
    try {
      const fields = await this._fetchTableData('sys_dictionary', {
        sysparm_fields: 'element,column_label,internal_type,max_length,reference',
        sysparm_query: `name=${tableName}^elementISNOTEMPTY`,
        sysparm_order_by: 'column_label',
        sysparm_limit: 500
      });

      return fields.map(field => ({
        name: this.extractValue(field.element),
        label: this.extractDisplayValue(field.column_label) || this.extractValue(field.element),
        type: this.extractValue(field.internal_type),
        maxLength: this.extractValue(field.max_length),
        reference: this.extractValue(field.reference)
      }));
    } catch (error) {
      console.error('Error fetching table fields:', error);
      return [];
    }
  }

  // Validation helpers
  validateExportDefinition(data) {
    const errors = [];

    if (!data.export_name?.trim()) {
      errors.push('Export name is required');
    }

    if (!data.target_table?.trim()) {
      errors.push('Target table is required');
    }

    if (data.batch_size && (isNaN(data.batch_size) || data.batch_size < 1 || data.batch_size > 10000)) {
      errors.push('Batch size must be between 1 and 10,000');
    }

    if (data.attachment_mode === 'write_attachment') {
      if (!data.attachment_table?.trim()) {
        errors.push('Attachment table is required when using write_attachment mode');
      }
      if (!data.attachment_record_id?.trim()) {
        errors.push('Attachment record ID is required when using write_attachment mode');
      }
    }

    return errors;
  }

  validateFieldMapping(data) {
    const errors = [];

    if (!data.header_label?.trim()) {
      errors.push('Header label is required');
    }

    if (!data.source_type) {
      errors.push('Source type is required');
    }

    if (data.source_type === 'field' && !data.source_field?.trim()) {
      errors.push('Source field is required for field type mapping');
    }

    if (data.source_type === 'related') {
      if (!data.source_table_alias?.trim()) {
        errors.push('Source table alias is required for related type mapping');
      }
      if (!data.source_field?.trim()) {
        errors.push('Source field is required for related type mapping');
      }
    }

    if (data.source_type === 'scripted' && !data.script_field?.trim()) {
      errors.push('Script field is required for scripted type mapping');
    }

    if (data.order_number && (isNaN(data.order_number) || data.order_number < 1)) {
      errors.push('Order number must be a positive integer');
    }

    return errors;
  }

  validateRelatedSource(data, existingAliases = []) {
    const errors = [];

    if (!data.alias?.trim()) {
      errors.push('Alias is required');
    } else if (existingAliases.includes(data.alias.trim())) {
      errors.push('Alias must be unique within the export definition');
    }

    if (!data.table?.trim()) {
      errors.push('Related table is required');
    }

    if (!data.relationship_field?.trim()) {
      errors.push('Relationship field is required');
    }

    if (data.flatten_mode === 'scripted' && !data.script?.trim()) {
      errors.push('Script is required when using scripted flatten mode');
    }

    return errors;
  }

  // Private API methods
  async _fetchTableData(tableName, params = {}) {
    try {
      const searchParams = new URLSearchParams(params);
      const response = await fetch(`/api/now/table/${tableName}?${searchParams.toString()}`, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'X-UserToken': window.g_ck
        }
      });

      if (!response.ok) {
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`;
        try {
          const errorData = await response.json();
          if (errorData.error?.message) {
            errorMessage = errorData.error.message;
          }
        } catch (e) {
          // Ignore JSON parse errors
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error(`Error fetching data from ${tableName}:`, error);
      throw new Error(`Failed to fetch data from ${tableName}: ${error.message}`);
    }
  }

  async _postTableData(tableName, data) {
    try {
      const response = await fetch(`/api/now/table/${tableName}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-UserToken': window.g_ck
        },
        body: JSON.stringify(data)
      });

      if (!response.ok) {
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`;
        try {
          const errorData = await response.json();
          if (errorData.error?.message) {
            errorMessage = errorData.error.message;
          }
        } catch (e) {
          // Ignore JSON parse errors
        }
        throw new Error(errorMessage);
      }

      const result = await response.json();
      return result.result;
    } catch (error) {
      console.error(`Error creating record in ${tableName}:`, error);
      throw new Error(`Failed to create record: ${error.message}`);
    }
  }

  async _putTableData(tableName, sysId, data) {
    try {
      const response = await fetch(`/api/now/table/${tableName}/${sysId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-UserToken': window.g_ck
        },
        body: JSON.stringify(data)
      });

      if (!response.ok) {
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`;
        try {
          const errorData = await response.json();
          if (errorData.error?.message) {
            errorMessage = errorData.error.message;
          }
        } catch (e) {
          // Ignore JSON parse errors
        }
        throw new Error(errorMessage);
      }

      const result = await response.json();
      return result.result;
    } catch (error) {
      console.error(`Error updating record in ${tableName}:`, error);
      throw new Error(`Failed to update record: ${error.message}`);
    }
  }

  async _deleteTableData(tableName, sysId) {
    try {
      const response = await fetch(`/api/now/table/${tableName}/${sysId}`, {
        method: 'DELETE',
        headers: {
          'Accept': 'application/json',
          'X-UserToken': window.g_ck
        }
      });

      if (!response.ok) {
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`;
        try {
          const errorData = await response.json();
          if (errorData.error?.message) {
            errorMessage = errorData.error.message;
          }
        } catch (e) {
          // Ignore JSON parse errors
        }
        throw new Error(errorMessage);
      }

      return true;
    } catch (error) {
      console.error(`Error deleting record from ${tableName}:`, error);
      throw new Error(`Failed to delete record: ${error.message}`);
    }
  }
}","import React, { useMemo } from 'react';
import { ExportConfigService } from '../services/ExportConfigService.js';
import './ConsoleLanding.css';

export default function ConsoleLanding({ 
  definitions, 
  loading, 
  onCreateNew, 
  onEditDefinition, 
  onManageMapping, 
  onManageRelated, 
  onTestExport, 
  onDeleteDefinition, 
  onRefresh 
}) {
  const configService = new ExportConfigService();

  const stats = useMemo(() => {
    const total = definitions.length;
    const active = definitions.filter(def => String(def.active) === 'true').length;
    const inactive = total - active;
    return { total, active, inactive };
  }, [definitions]);

  const handleDelete = async (definition) => {
    const defName = configService.extractDisplayValue(definition.export_name);
    if (window.confirm(`Are you sure you want to delete "${defName}"? This action cannot be undone.`)) {
      try {
        await configService.deleteExportDefinition(configService.extractValue(definition.sys_id));
        onDeleteDefinition(configService.extractValue(definition.sys_id));
      } catch (error) {
        alert('Failed to delete export definition: ' + error.message);
      }
    }
  };

  if (loading) {
    return (
      <div className="landing-loading">
        <div className="loading-spinner"></div>
        <div className="loading-text">Loading export definitions...</div>
      </div>
    );
  }

  return (
    <div className="console-landing">
      <div className="landing-header">
        <div className="header-actions">
          <button onClick={onCreateNew} className="btn btn-primary btn-lg">
            + Create New CSV Export Definition
          </button>
          <button onClick={onRefresh} className="btn btn-outline">
            Refresh
          </button>
        </div>
      </div>

      <div className="stats-overview">
        <div className="stat-card">
          <div className="stat-number">{stats.total}</div>
          <div className="stat-label">Total Definitions</div>
        </div>
        <div className="stat-card active">
          <div className="stat-number">{stats.active}</div>
          <div className="stat-label">Active</div>
        </div>
        <div className="stat-card inactive">
          <div className="stat-number">{stats.inactive}</div>
          <div className="stat-label">Inactive</div>
        </div>
      </div>

      <div className="definitions-section">
        <h2>Export Definitions</h2>

        {definitions.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">📋</div>
            <h3>No Export Definitions Yet</h3>
            <p>Get started by creating your first CSV export definition.</p>
            <button onClick={onCreateNew} className="btn btn-primary">
              Create Your First Export
            </button>
          </div>
        ) : (
          <div className="definitions-grid">
            {definitions.map(definition => {
              const defName = configService.extractDisplayValue(definition.export_name);
              const targetTable = configService.extractDisplayValue(definition.target_table);
              const isActive = String(definition.active) === 'true';
              const lastModified = new Date(configService.extractValue(definition.sys_updated_on));

              return (
                <div key={configService.extractValue(definition.sys_id)} className="definition-card">
                  <div className="card-header">
                    <div className="definition-title">
                      <h3>{defName}</h3>
                      <span className={`status-badge ${isActive ? 'active' : 'inactive'}`}>
                        {isActive ? 'Active' : 'Inactive'}
                      </span>
                    </div>
                  </div>

                  <div className="card-body">
                    <div className="definition-info">
                      <div className="info-item">
                        <label>Target Table:</label>
                        <span>{targetTable}</span>
                      </div>
                      <div className="info-item">
                        <label>Last Modified:</label>
                        <span>{lastModified.toLocaleDateString()}</span>
                      </div>
                      {definition.description && (
                        <div className="info-item description">
                          <label>Description:</label>
                          <span>{configService.extractDisplayValue(definition.description)}</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="card-footer">
                    <div className="action-buttons">
                      <button 
                        onClick={() => onEditDefinition(definition)} 
                        className="btn btn-sm btn-outline"
                        title="Edit Definition"
                      >
                        Edit
                      </button>
                      <button 
                        onClick={() => onManageMapping(definition)} 
                        className="btn btn-sm btn-outline"
                        title="Manage Field Mappings"
                      >
                        Fields
                      </button>
                      <button 
                        onClick={() => onManageRelated(definition)} 
                        className="btn btn-sm btn-outline"
                        title="Manage Related Sources"
                      >
                        Related
                      </button>
                      <button 
                        onClick={() => onTestExport(definition)} 
                        className="btn btn-sm btn-success"
                        title="Test Export"
                      >
                        Test
                      </button>
                      <button 
                        onClick={() => handleDelete(definition)} 
                        className="btn btn-sm btn-danger"
                        title="Delete Definition"
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div className="quick-links">
        <h3>Quick Links</h3>
        <div className="links-grid">
          <a href="x_271493_dynamic_c_export_definition_list.do" className="quick-link">
            <div className="link-icon">📊</div>
            <div className="link-content">
              <h4>All Export Definitions</h4>
              <p>View and manage all definitions in list view</p>
            </div>
          </a>
          <a href="x_271493_dynamic_c_export_mapping_list.do" className="quick-link">
            <div className="link-icon">🔗</div>
            <div className="link-content">
              <h4>Field Mappings</h4>
              <p>Browse all field mapping configurations</p>
            </div>
          </a>
          <a href="x_271493_dynamic_c_csv_related_source_list.do" className="quick-link">
            <div className="link-icon">🔄</div>
            <div className="link-content">
              <h4>Related Sources</h4>
              <p>Manage related table configurations</p>
            </div>
          </a>
          <a href="x_271493_dynamic_c_csv_export_dashboard.do" className="quick-link">
            <div className="link-icon">📈</div>
            <div className="link-content">
              <h4>Analytics Dashboard</h4>
              <p>View export performance and usage analytics</p>
            </div>
          </a>
        </div>
      </div>
    </div>
  );
}","import React, { useState, useEffect, useMemo } from 'react';
import { ExportConfigService } from '../services/ExportConfigService.js';

export default function ExportDefinitionWizard({ definition, onCancel, onComplete, onUpdate }) {
  const configService = useMemo(() => new ExportConfigService(), []);
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [tables, setTables] = useState([]);
  const [formData, setFormData] = useState({
    export_name: '',
    active: true,
    target_table: '',
    delimiter: 'comma',
    batch_size: 1000,
    description: '',
    encoded_query: '',
    filter_script: '',
    attachment_mode: 'none',
    attachment_table: '',
    attachment_record_id: ''
  });
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});

  const isEditing = !!definition;
  const totalSteps = 4;

  // Load existing definition data
  useEffect(() => {
    if (definition) {
      setFormData({
        export_name: configService.extractDisplayValue(definition.export_name) || '',
        active: String(definition.active) === 'true',
        target_table: configService.extractValue(definition.target_table) || '',
        delimiter: configService.extractValue(definition.delimiter) || 'comma',
        batch_size: parseInt(configService.extractValue(definition.batch_size)) || 1000,
        description: configService.extractDisplayValue(definition.description) || '',
        encoded_query: configService.extractValue(definition.encoded_query) || '',
        filter_script: configService.extractValue(definition.filter_script) || '',
        attachment_mode: configService.extractValue(definition.attachment_mode) || 'none',
        attachment_table: configService.extractValue(definition.attachment_table) || '',
        attachment_record_id: configService.extractValue(definition.attachment_record_id) || ''
      });
    }
  }, [definition, configService]);

  // Load table list
  useEffect(() => {
    const loadTables = async () => {
      try {
        const tableList = await configService.getTableList();
        setTables(tableList);
      } catch (error) {
        console.error('Failed to load tables:', error);
      }
    };
    loadTables();
  }, [configService]);

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setTouched(prev => ({ ...prev, [field]: true }));

    // Clear errors for this field
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: null }));
    }
  };

  const validateStep = (step) => {
    const newErrors = {};

    switch (step) {
      case 1: // Basic Settings
        if (!formData.export_name.trim()) {
          newErrors.export_name = 'Export name is required';
        }
        if (!formData.target_table) {
          newErrors.target_table = 'Target table is required';
        }
        if (formData.batch_size < 1 || formData.batch_size > 10000) {
          newErrors.batch_size = 'Batch size must be between 1 and 10,000';
        }
        break;

      case 3: // Attachment Settings
        if (formData.attachment_mode === 'write_attachment') {
          if (!formData.attachment_table.trim()) {
            newErrors.attachment_table = 'Attachment table is required for write_attachment mode';
          }
          if (!formData.attachment_record_id.trim()) {
            newErrors.attachment_record_id = 'Attachment record ID is required for write_attachment mode';
          }
        }
        break;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const nextStep = () => {
    if (validateStep(currentStep)) {
      setCurrentStep(prev => Math.min(prev + 1, totalSteps));
    }
  };

  const prevStep = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
  };

  const handleSubmit = async () => {
    if (!validateStep(currentStep)) {
      return;
    }

    try {
      setLoading(true);

      const submitData = {
        export_name: formData.export_name.trim(),
        active: formData.active,
        target_table: formData.target_table,
        delimiter: formData.delimiter,
        batch_size: formData.batch_size,
        description: formData.description.trim(),
        encoded_query: formData.encoded_query.trim(),
        filter_script: formData.filter_script.trim(),
        attachment_mode: formData.attachment_mode,
        attachment_table: formData.attachment_table.trim(),
        attachment_record_id: formData.attachment_record_id.trim()
      };

      if (isEditing) {
        const updated = await configService.updateExportDefinition(
          configService.extractValue(definition.sys_id), 
          submitData
        );
        onUpdate(updated);
      } else {
        const created = await configService.createExportDefinition(submitData);
        onComplete(created);
      }
    } catch (error) {
      setErrors({ submit: error.message });
    } finally {
      setLoading(false);
    }
  };

  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return (
          <div className="wizard-step">
            <h3>Basic Settings</h3>
            <p>Configure the fundamental settings for your CSV export.</p>

            <div className="form-group">
              <label className="form-label">Export Name *</label>
              <input
                type="text"
                className={`form-control ${errors.export_name ? 'is-invalid' : ''}`}
                value={formData.export_name}
                onChange={(e) => handleInputChange('export_name', e.target.value)}
                placeholder="Enter a descriptive name for this export"
              />
              {errors.export_name && <div className="invalid-feedback">{errors.export_name}</div>}
              <div className="form-text">Choose a clear, descriptive name that identifies the purpose of this export.</div>
            </div>

            <div className="form-group">
              <label className="form-label">Target Table *</label>
              <select
                className={`form-control ${errors.target_table ? 'is-invalid' : ''}`}
                value={formData.target_table}
                onChange={(e) => handleInputChange('target_table', e.target.value)}
              >
                <option value="">Select a table...</option>
                {tables.map(table => (
                  <option key={table.name} value={table.name}>
                    {table.label} ({table.name})
                  </option>
                ))}
              </select>
              {errors.target_table && <div className="invalid-feedback">{errors.target_table}</div>}
              <div className="form-text">The primary table from which data will be exported.</div>
            </div>

            <div className="form-group">
              <label className="form-label">Active</label>
              <div className="form-check">
                <input
                  type="checkbox"
                  className="form-check-input"
                  checked={formData.active}
                  onChange={(e) => handleInputChange('active', e.target.checked)}
                />
                <label className="form-check-label">
                  Enable this export definition
                </label>
              </div>
              <div className="form-text">Inactive definitions cannot be executed.</div>
            </div>

            <div className="form-row">
              <div className="form-group col-md-6">
                <label className="form-label">Delimiter</label>
                <select
                  className="form-control"
                  value={formData.delimiter}
                  onChange={(e) => handleInputChange('delimiter', e.target.value)}
                >
                  <option value="comma">Comma (,)</option>
                  <option value="semicolon">Semicolon (;)</option>
                </select>
                <div className="form-text">Choose the CSV field separator.</div>
              </div>

              <div className="form-group col-md-6">
                <label className="form-label">Batch Size</label>
                <input
                  type="number"
                  className={`form-control ${errors.batch_size ? 'is-invalid' : ''}`}
                  value={formData.batch_size}
                  onChange={(e) => handleInputChange('batch_size', parseInt(e.target.value) || 0)}
                  min="1"
                  max="10000"
                />
                {errors.batch_size && <div className="invalid-feedback">{errors.batch_size}</div>}
                <div className="form-text">Number of records to process at once (1-10,000).</div>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Description</label>
              <textarea
                className="form-control"
                value={formData.description}
                onChange={(e) => handleInputChange('description', e.target.value)}
                rows="3"
                placeholder="Optional description of what this export does..."
              />
              <div className="form-text">Optional description to help identify the purpose of this export.</div>
            </div>
          </div>
        );

      case 2:
        return (
          <div className="wizard-step">
            <h3>Query & Filter Logic</h3>
            <p>Define how records should be filtered for export.</p>

            <div className="form-group">
              <label className="form-label">Encoded Query</label>
              <textarea
                className="form-control"
                value={formData.encoded_query}
                onChange={(e) => handleInputChange('encoded_query', e.target.value)}
                rows="3"
                placeholder="e.g., active=true^state=1"
              />
              <div className="form-text">
                ServiceNow encoded query string to filter records. Leave empty to export all records.
                <br />
                <strong>Example:</strong> active=true^state=1^opened_atONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Filter Script</label>
              <textarea
                className="form-control"
                value={formData.filter_script}
                onChange={(e) => handleInputChange('filter_script', e.target.value)}
                rows="8"
                placeholder="// Return true to include record, false to exclude
// Available variables: current (GlideRecord)
// Example:
return current.getValue('state') == 'Active';"
              />
              <div className="form-text">
                Optional JavaScript code to apply additional filtering logic to each record.
                <br />
                <strong>Available variables:</strong> current (GlideRecord of the target table)
                <br />
                <strong>Return:</strong> true to include the record, false to exclude it
              </div>
            </div>

            <div className="info-box">
              <h4>Filtering Priority</h4>
              <ol>
                <li><strong>Encoded Query:</strong> Applied first at the database level</li>
                <li><strong>Filter Script:</strong> Applied to each record after database filtering</li>
              </ol>
              <p>For best performance, use encoded queries for simple conditions and filter scripts for complex logic.</p>
            </div>
          </div>
        );

      case 3:
        return (
          <div className="wizard-step">
            <h3>Attachment Settings</h3>
            <p>Configure how the generated CSV file should be handled.</p>

            <div className="form-group">
              <label className="form-label">Attachment Mode</label>
              <select
                className="form-control"
                value={formData.attachment_mode}
                onChange={(e) => handleInputChange('attachment_mode', e.target.value)}
              >
                <option value="none">None (Return CSV content)</option>
                <option value="return">Return Attachment Reference</option>
                <option value="write_attachment">Write to Attachment Table</option>
              </select>
              <div className="form-text">
                <strong>None:</strong> CSV content returned directly in response
                <br />
                <strong>Return:</strong> Creates temporary attachment and returns reference
                <br />
                <strong>Write:</strong> Attaches CSV file to specified table record
              </div>
            </div>

            {formData.attachment_mode === 'write_attachment' && (
              <>
                <div className="form-group">
                  <label className="form-label">Attachment Table *</label>
                  <input
                    type="text"
                    className={`form-control ${errors.attachment_table ? 'is-invalid' : ''}`}
                    value={formData.attachment_table}
                    onChange={(e) => handleInputChange('attachment_table', e.target.value)}
                    placeholder="e.g., incident, task, sys_user"
                  />
                  {errors.attachment_table && <div className="invalid-feedback">{errors.attachment_table}</div>}
                  <div className="form-text">Table name where the CSV file will be attached.</div>
                </div>

                <div className="form-group">
                  <label className="form-label">Attachment Record ID *</label>
                  <input
                    type="text"
                    className={`form-control ${errors.attachment_record_id ? 'is-invalid' : ''}`}
                    value={formData.attachment_record_id}
                    onChange={(e) => handleInputChange('attachment_record_id', e.target.value)}
                    placeholder="sys_id of the record to attach to"
                  />
                  {errors.attachment_record_id && <div className="invalid-feedback">{errors.attachment_record_id}</div>}
                  <div className="form-text">The sys_id of the specific record where the CSV will be attached.</div>
                </div>
              </>
            )}
          </div>
        );

      case 4:
        return (
          <div className="wizard-step">
            <h3>Review & Save</h3>
            <p>Review your export definition settings before saving.</p>

            <div className="review-section">
              <h4>Basic Settings</h4>
              <div className="review-grid">
                <div className="review-item">
                  <label>Export Name:</label>
                  <span>{formData.export_name}</span>
                </div>
                <div className="review-item">
                  <label>Status:</label>
                  <span className={formData.active ? 'status-active' : 'status-inactive'}>
                    {formData.active ? 'Active' : 'Inactive'}
                  </span>
                </div>
                <div className="review-item">
                  <label>Target Table:</label>
                  <span>{tables.find(t => t.name === formData.target_table)?.label || formData.target_table}</span>
                </div>
                <div className="review-item">
                  <label>Delimiter:</label>
                  <span>{formData.delimiter === 'comma' ? 'Comma (,)' : 'Semicolon (;)'}</span>
                </div>
                <div className="review-item">
                  <label>Batch Size:</label>
                  <span>{formData.batch_size.toLocaleString()}</span>
                </div>
              </div>
            </div>

            <div className="review-section">
              <h4>Filtering</h4>
              <div className="review-grid">
                <div className="review-item">
                  <label>Encoded Query:</label>
                  <span>{formData.encoded_query || 'None (all records)'}</span>
                </div>
                <div className="review-item">
                  <label>Filter Script:</label>
                  <span>{formData.filter_script ? 'Custom script defined' : 'None'}</span>
                </div>
              </div>
            </div>

            <div className="review-section">
              <h4>Attachment Settings</h4>
              <div className="review-grid">
                <div className="review-item">
                  <label>Mode:</label>
                  <span>
                    {formData.attachment_mode === 'none' && 'Return CSV content'}
                    {formData.attachment_mode === 'return' && 'Return attachment reference'}
                    {formData.attachment_mode === 'write_attachment' && 'Write to attachment table'}
                  </span>
                </div>
                {formData.attachment_mode === 'write_attachment' && (
                  <>
                    <div className="review-item">
                      <label>Attachment Table:</label>
                      <span>{formData.attachment_table}</span>
                    </div>
                    <div className="review-item">
                      <label>Record ID:</label>
                      <span>{formData.attachment_record_id}</span>
                    </div>
                  </>
                )}
              </div>
            </div>

            {formData.description && (
              <div className="review-section">
                <h4>Description</h4>
                <p>{formData.description}</p>
              </div>
            )}

            {errors.submit && (
              <div className="error-message">
                <strong>Error:</strong> {errors.submit}
              </div>
            )}
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="wizard-container">
      <div className="wizard-header">
        <h2>{isEditing ? 'Edit Export Definition' : 'Create New Export Definition'}</h2>

        {/* Progress indicator */}
        <div className="wizard-progress">
          {Array.from({ length: totalSteps }, (_, i) => (
            <div 
              key={i + 1} 
              className={`progress-step ${i + 1 <= currentStep ? 'active' : ''} ${i + 1 < currentStep ? 'completed' : ''}`}
            >
              <div className="step-number">{i + 1}</div>
              <div className="step-label">
                {i + 1 === 1 && 'Basic Settings'}
                {i + 1 === 2 && 'Query & Filter'}
                {i + 1 === 3 && 'Attachment'}
                {i + 1 === 4 && 'Review'}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="wizard-content">
        {renderStep()}
      </div>

      <div className="wizard-footer">
        <div className="footer-actions">
          <button onClick={onCancel} className="btn btn-outline">
            Cancel
          </button>

          <div className="step-actions">
            {currentStep > 1 && (
              <button onClick={prevStep} className="btn btn-secondary">
                Previous
              </button>
            )}

            {currentStep < totalSteps ? (
              <button onClick={nextStep} className="btn btn-primary">
                Next
              </button>
            ) : (
              <button 
                onClick={handleSubmit} 
                className="btn btn-success"
                disabled={loading}
              >
                {loading ? 'Saving...' : (isEditing ? 'Update Definition' : 'Create Definition')}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}","import React, { useState, useEffect, useMemo } from 'react';
import { ExportConfigService } from '../services/ExportConfigService.js';

export default function FieldMappingManager({ definition, onBack, onDefinitionSelect, definitions }) {
  const configService = useMemo(() => new ExportConfigService(), []);
  const [mappings, setMappings] = useState([]);
  const [relatedSources, setRelatedSources] = useState([]);
  const [targetFields, setTargetFields] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingMapping, setEditingMapping] = useState(null);
  const [formData, setFormData] = useState({
    header_label: '',
    order_number: 100,
    source_type: 'field',
    source_table_alias: '',
    source_field: '',
    script_field: ''
  });
  const [errors, setErrors] = useState({});

  const selectedDefinition = definition || definitions[0];
  const definitionId = selectedDefinition ? configService.extractValue(selectedDefinition.sys_id) : null;

  useEffect(() => {
    if (definitionId) {
      loadMappings();
      loadRelatedSources();
      loadTargetFields();
    }
  }, [definitionId]);

  const loadMappings = async () => {
    try {
      setLoading(true);
      const data = await configService.getFieldMappings(definitionId);
      setMappings(data);
    } catch (error) {
      console.error('Failed to load mappings:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadRelatedSources = async () => {
    try {
      const data = await configService.getRelatedSources(definitionId);
      setRelatedSources(data);
    } catch (error) {
      console.error('Failed to load related sources:', error);
    }
  };

  const loadTargetFields = async () => {
    if (!selectedDefinition) return;
    try {
      const tableName = configService.extractValue(selectedDefinition.target_table);
      const fields = await configService.getTableFields(tableName);
      setTargetFields(fields);
    } catch (error) {
      console.error('Failed to load target fields:', error);
    }
  };

  const handleAddMapping = () => {
    setEditingMapping(null);
    setFormData({
      header_label: '',
      order_number: Math.max(...mappings.map(m => parseInt(configService.extractValue(m.order_number)) || 0), 0) + 10,
      source_type: 'field',
      source_table_alias: '',
      source_field: '',
      script_field: ''
    });
    setErrors({});
    setShowForm(true);
  };

  const handleEditMapping = (mapping) => {
    setEditingMapping(mapping);
    setFormData({
      header_label: configService.extractDisplayValue(mapping.header_label) || '',
      order_number: parseInt(configService.extractValue(mapping.order_number)) || 100,
      source_type: configService.extractValue(mapping.source_type) || 'field',
      source_table_alias: configService.extractValue(mapping.source_table_alias) || '',
      source_field: configService.extractValue(mapping.source_field) || '',
      script_field: configService.extractValue(mapping.script_field) || ''
    });
    setErrors({});
    setShowForm(true);
  };

  const handleDeleteMapping = async (mapping) => {
    const headerLabel = configService.extractDisplayValue(mapping.header_label);
    if (window.confirm(`Delete field mapping "${headerLabel}"?`)) {
      try {
        await configService.deleteFieldMapping(configService.extractValue(mapping.sys_id));
        loadMappings();
      } catch (error) {
        alert('Failed to delete mapping: ' + error.message);
      }
    }
  };

  const handleSubmitMapping = async (e) => {
    e.preventDefault();

    const validationErrors = configService.validateFieldMapping(formData);
    if (validationErrors.length > 0) {
      setErrors({ submit: validationErrors.join(', ') });
      return;
    }

    try {
      const submitData = {
        ...formData,
        export_definition: definitionId
      };

      if (editingMapping) {
        await configService.updateFieldMapping(
          configService.extractValue(editingMapping.sys_id),
          submitData
        );
      } else {
        await configService.createFieldMapping(submitData);
      }

      setShowForm(false);
      loadMappings();
    } catch (error) {
      setErrors({ submit: error.message });
    }
  };

  if (!selectedDefinition) {
    return (
      <div className="mapping-manager">
        <div className="manager-header">
          <button onClick={onBack} className="btn btn-outline">← Back to Console</button>
          <h2>Field Mapping Manager</h2>
        </div>
        <div className="empty-state">
          <p>Please select an export definition to manage its field mappings.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mapping-manager">
      <div className="manager-header">
        <button onClick={onBack} className="btn btn-outline">← Back to Console</button>
        <h2>Field Mapping Manager</h2>

        {definitions.length > 1 && (
          <div className="definition-selector">
            <label>Export Definition:</label>
            <select
              value={configService.extractValue(selectedDefinition.sys_id)}
              onChange={(e) => {
                const selected = definitions.find(d => 
                  configService.extractValue(d.sys_id) === e.target.value
                );
                onDefinitionSelect(selected);
              }}
              className="form-control"
            >
              {definitions.map(def => (
                <option key={configService.extractValue(def.sys_id)} value={configService.extractValue(def.sys_id)}>
                  {configService.extractDisplayValue(def.export_name)}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      <div className="manager-content">
        <div className="content-header">
          <h3>
            Field Mappings for: {configService.extractDisplayValue(selectedDefinition.export_name)}
          </h3>
          <button onClick={handleAddMapping} className="btn btn-primary">
            + Add Field Mapping
          </button>
        </div>

        {loading ? (
          <div className="loading-state">
            <div className="loading-spinner"></div>
            <div className="loading-text">Loading field mappings...</div>
          </div>
        ) : (
          <>
            {mappings.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">🔗</div>
                <h3>No Field Mappings Yet</h3>
                <p>Add field mappings to define which data columns will appear in your CSV export.</p>
                <button onClick={handleAddMapping} className="btn btn-primary">
                  Add First Field Mapping
                </button>
              </div>
            ) : (
              <div className="mappings-table">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Order</th>
                      <th>Header Label</th>
                      <th>Source Type</th>
                      <th>Source Details</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {mappings
                      .sort((a, b) => 
                        (parseInt(configService.extractValue(a.order_number)) || 0) - 
                        (parseInt(configService.extractValue(b.order_number)) || 0)
                      )
                      .map(mapping => (
                        <tr key={configService.extractValue(mapping.sys_id)}>
                          <td>{configService.extractValue(mapping.order_number)}</td>
                          <td className="header-cell">
                            {configService.extractDisplayValue(mapping.header_label)}
                          </td>
                          <td>
                            <span className={`type-badge ${configService.extractValue(mapping.source_type)}`}>
                              {configService.extractDisplayValue(mapping.source_type)}
                            </span>
                          </td>
                          <td className="source-details">
                            {configService.extractValue(mapping.source_type) === 'field' && (
                              <span>Field: {configService.extractValue(mapping.source_field)}</span>
                            )}
                            {configService.extractValue(mapping.source_type) === 'related' && (
                              <span>
                                Alias: {configService.extractValue(mapping.source_table_alias)} → 
                                Field: {configService.extractValue(mapping.source_field)}
                              </span>
                            )}
                            {configService.extractValue(mapping.source_type) === 'scripted' && (
                              <span>Custom Script</span>
                            )}
                          </td>
                          <td className="actions-cell">
                            <button 
                              onClick={() => handleEditMapping(mapping)}
                              className="btn btn-sm btn-outline"
                            >
                              Edit
                            </button>
                            <button 
                              onClick={() => handleDeleteMapping(mapping)}
                              className="btn btn-sm btn-danger"
                            >
                              Delete
                            </button>
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}
      </div>

      {showForm && (
        <div className="modal-overlay">
          <div className="modal-dialog">
            <form onSubmit={handleSubmitMapping} className="mapping-form">
              <div className="modal-header">
                <h3>{editingMapping ? 'Edit Field Mapping' : 'Add Field Mapping'}</h3>
                <button 
                  type="button" 
                  onClick={() => setShowForm(false)}
                  className="close-button"
                >
                  ×
                </button>
              </div>

              <div className="modal-body">
                <div className="form-row">
                  <div className="form-group col-md-6">
                    <label className="form-label">Header Label *</label>
                    <input
                      type="text"
                      className="form-control"
                      value={formData.header_label}
                      onChange={(e) => setFormData(prev => ({...prev, header_label: e.target.value}))}
                      placeholder="Column header in CSV"
                      required
                    />
                  </div>
                  <div className="form-group col-md-6">
                    <label className="form-label">Order Number *</label>
                    <input
                      type="number"
                      className="form-control"
                      value={formData.order_number}
                      onChange={(e) => setFormData(prev => ({...prev, order_number: parseInt(e.target.value) || 0}))}
                      min="1"
                      required
                    />
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Source Type *</label>
                  <select
                    className="form-control"
                    value={formData.source_type}
                    onChange={(e) => setFormData(prev => ({...prev, source_type: e.target.value}))}
                    required
                  >
                    <option value="field">Direct Field</option>
                    <option value="related">Related Table Field</option>
                    <option value="scripted">Scripted Value</option>
                  </select>
                </div>

                {formData.source_type === 'field' && (
                  <div className="form-group">
                    <label className="form-label">Source Field *</label>
                    <select
                      className="form-control"
                      value={formData.source_field}
                      onChange={(e) => setFormData(prev => ({...prev, source_field: e.target.value}))}
                      required
                    >
                      <option value="">Select field...</option>
                      {targetFields.map(field => (
                        <option key={field.name} value={field.name}>
                          {field.label} ({field.name})
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                {formData.source_type === 'related' && (
                  <>
                    <div className="form-group">
                      <label className="form-label">Source Table Alias *</label>
                      <select
                        className="form-control"
                        value={formData.source_table_alias}
                        onChange={(e) => setFormData(prev => ({...prev, source_table_alias: e.target.value}))}
                        required
                      >
                        <option value="">Select alias...</option>
                        {relatedSources.map(source => (
                          <option key={configService.extractValue(source.sys_id)} value={configService.extractValue(source.alias)}>
                            {configService.extractValue(source.alias)} ({configService.extractDisplayValue(source.table)})
                          </option>
                        ))}
                      </select>
                      {relatedSources.length === 0 && (
                        <div className="form-text text-warning">
                          No related sources defined. Add related sources first to use this option.
                        </div>
                      )}
                    </div>
                    <div className="form-group">
                      <label className="form-label">Source Field *</label>
                      <input
                        type="text"
                        className="form-control"
                        value={formData.source_field}
                        onChange={(e) => setFormData(prev => ({...prev, source_field: e.target.value}))}
                        placeholder="Field name in related table"
                        required
                      />
                    </div>
                  </>
                )}

                {formData.source_type === 'scripted' && (
                  <div className="form-group">
                    <label className="form-label">Script Field *</label>
                    <textarea
                      className="form-control"
                      value={formData.script_field}
                      onChange={(e) => setFormData(prev => ({...prev, script_field: e.target.value}))}
                      rows="6"
                      placeholder="// Return computed value
// Available: current (GlideRecord)
return current.getValue('field_name');"
                      required
                    />
                    <div className="form-text">
                      JavaScript code to compute the field value. Must return a string.
                    </div>
                  </div>
                )}

                {errors.submit && (
                  <div className="error-message">
                    {errors.submit}
                  </div>
                )}
              </div>

              <div className="modal-footer">
                <button type="button" onClick={() => setShowForm(false)} className="btn btn-outline">
                  Cancel
                </button>
                <button type="submit" className="btn btn-success">
                  {editingMapping ? 'Update Mapping' : 'Add Mapping'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}","import React, { useState, useEffect, useMemo } from 'react';
import { ExportConfigService } from '../services/ExportConfigService.js';

export default function RelatedSourceManager({ definition, onBack, onDefinitionSelect, definitions }) {
  const configService = useMemo(() => new ExportConfigService(), []);
  const [sources, setSources] = useState([]);
  const [tables, setTables] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingSource, setEditingSource] = useState(null);
  const [formData, setFormData] = useState({
    alias: '',
    table: '',
    relationship_field: '',
    one_to_one: false,
    flatten_mode: 'first',
    script: ''
  });
  const [errors, setErrors] = useState({});

  const selectedDefinition = definition || definitions[0];
  const definitionId = selectedDefinition ? configService.extractValue(selectedDefinition.sys_id) : null;

  useEffect(() => {
    if (definitionId) {
      loadSources();
    }
    loadTables();
  }, [definitionId]);

  const loadSources = async () => {
    try {
      setLoading(true);
      const data = await configService.getRelatedSources(definitionId);
      setSources(data);
    } catch (error) {
      console.error('Failed to load related sources:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadTables = async () => {
    try {
      const tableList = await configService.getTableList();
      setTables(tableList);
    } catch (error) {
      console.error('Failed to load tables:', error);
    }
  };

  const handleAddSource = () => {
    setEditingSource(null);
    setFormData({
      alias: '',
      table: '',
      relationship_field: '',
      one_to_one: false,
      flatten_mode: 'first',
      script: ''
    });
    setErrors({});
    setShowForm(true);
  };

  const handleEditSource = (source) => {
    setEditingSource(source);
    setFormData({
      alias: configService.extractValue(source.alias) || '',
      table: configService.extractValue(source.table) || '',
      relationship_field: configService.extractValue(source.relationship_field) || '',
      one_to_one: String(source.one_to_one) === 'true',
      flatten_mode: configService.extractValue(source.flatten_mode) || 'first',
      script: configService.extractValue(source.script) || ''
    });
    setErrors({});
    setShowForm(true);
  };

  const handleDeleteSource = async (source) => {
    const alias = configService.extractValue(source.alias);
    if (window.confirm(`Delete related source "${alias}"?`)) {
      try {
        await configService.deleteRelatedSource(configService.extractValue(source.sys_id));
        loadSources();
      } catch (error) {
        alert('Failed to delete related source: ' + error.message);
      }
    }
  };

  const handleSubmitSource = async (e) => {
    e.preventDefault();

    const existingAliases = sources
      .filter(s => !editingSource || configService.extractValue(s.sys_id) !== configService.extractValue(editingSource.sys_id))
      .map(s => configService.extractValue(s.alias));

    const validationErrors = configService.validateRelatedSource(formData, existingAliases);
    if (validationErrors.length > 0) {
      setErrors({ submit: validationErrors.join(', ') });
      return;
    }

    try {
      const submitData = {
        ...formData,
        export_definition: definitionId
      };

      if (editingSource) {
        await configService.updateRelatedSource(
          configService.extractValue(editingSource.sys_id),
          submitData
        );
      } else {
        await configService.createRelatedSource(submitData);
      }

      setShowForm(false);
      loadSources();
    } catch (error) {
      setErrors({ submit: error.message });
    }
  };

  if (!selectedDefinition) {
    return (
      <div className="related-manager">
        <div className="manager-header">
          <button onClick={onBack} className="btn btn-outline">← Back to Console</button>
          <h2>Related Source Manager</h2>
        </div>
        <div className="empty-state">
          <p>Please select an export definition to manage its related sources.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="related-manager">
      <div className="manager-header">
        <button onClick={onBack} className="btn btn-outline">← Back to Console</button>
        <h2>Related Source Manager</h2>

        {definitions.length > 1 && (
          <div className="definition-selector">
            <label>Export Definition:</label>
            <select
              value={configService.extractValue(selectedDefinition.sys_id)}
              onChange={(e) => {
                const selected = definitions.find(d => 
                  configService.extractValue(d.sys_id) === e.target.value
                );
                onDefinitionSelect(selected);
              }}
              className="form-control"
            >
              {definitions.map(def => (
                <option key={configService.extractValue(def.sys_id)} value={configService.extractValue(def.sys_id)}>
                  {configService.extractDisplayValue(def.export_name)}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      <div className="manager-content">
        <div className="content-header">
          <h3>
            Related Sources for: {configService.extractDisplayValue(selectedDefinition.export_name)}
          </h3>
          <button onClick={handleAddSource} className="btn btn-primary">
            + Add Related Source
          </button>
        </div>

        <div className="info-box">
          <h4>About Related Sources</h4>
          <p>
            Related sources allow you to include data from tables related to your main export table. 
            Each source is given an alias that can be referenced in field mappings.
          </p>
        </div>

        {loading ? (
          <div className="loading-state">
            <div className="loading-spinner"></div>
            <div className="loading-text">Loading related sources...</div>
          </div>
        ) : (
          <>
            {sources.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">🔄</div>
                <h3>No Related Sources Yet</h3>
                <p>Add related sources to include data from other tables in your CSV export.</p>
                <button onClick={handleAddSource} className="btn btn-primary">
                  Add First Related Source
                </button>
              </div>
            ) : (
              <div className="sources-grid">
                {sources.map(source => (
                  <div key={configService.extractValue(source.sys_id)} className="source-card">
                    <div className="card-header">
                      <h4>{configService.extractValue(source.alias)}</h4>
                      <div className="card-actions">
                        <button 
                          onClick={() => handleEditSource(source)}
                          className="btn btn-sm btn-outline"
                        >
                          Edit
                        </button>
                        <button 
                          onClick={() => handleDeleteSource(source)}
                          className="btn btn-sm btn-danger"
                        >
                          Delete
                        </button>
                      </div>
                    </div>
                    <div className="card-body">
                      <div className="source-details">
                        <div className="detail-item">
                          <label>Table:</label>
                          <span>{configService.extractDisplayValue(source.table)}</span>
                        </div>
                        <div className="detail-item">
                          <label>Relationship Field:</label>
                          <span>{configService.extractValue(source.relationship_field)}</span>
                        </div>
                        <div className="detail-item">
                          <label>Type:</label>
                          <span>{String(source.one_to_one) === 'true' ? 'One-to-One' : 'One-to-Many'}</span>
                        </div>
                        <div className="detail-item">
                          <label>Flatten Mode:</label>
                          <span className={`flatten-mode ${configService.extractValue(source.flatten_mode)}`}>
                            {configService.extractDisplayValue(source.flatten_mode)}
                          </span>
                        </div>
                        {configService.extractValue(source.flatten_mode) === 'scripted' && (
                          <div className="detail-item">
                            <label>Custom Script:</label>
                            <span>✓ Defined</span>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}
      </div>

      {showForm && (
        <div className="modal-overlay">
          <div className="modal-dialog">
            <form onSubmit={handleSubmitSource} className="source-form">
              <div className="modal-header">
                <h3>{editingSource ? 'Edit Related Source' : 'Add Related Source'}</h3>
                <button 
                  type="button" 
                  onClick={() => setShowForm(false)}
                  className="close-button"
                >
                  ×
                </button>
              </div>

              <div className="modal-body">
                <div className="form-group">
                  <label className="form-label">Alias *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={formData.alias}
                    onChange={(e) => setFormData(prev => ({...prev, alias: e.target.value}))}
                    placeholder="Short identifier (e.g., 'usr', 'mgr')"
                    pattern="[a-zA-Z_][a-zA-Z0-9_]*"
                    title="Must start with letter or underscore, followed by letters, numbers, or underscores"
                    required
                  />
                  <div className="form-text">
                    Unique alias to reference this source in field mappings. Use short, descriptive names.
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Related Table *</label>
                  <select
                    className="form-control"
                    value={formData.table}
                    onChange={(e) => setFormData(prev => ({...prev, table: e.target.value}))}
                    required
                  >
                    <option value="">Select table...</option>
                    {tables.map(table => (
                      <option key={table.name} value={table.name}>
                        {table.label} ({table.name})
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label className="form-label">Relationship Field *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={formData.relationship_field}
                    onChange={(e) => setFormData(prev => ({...prev, relationship_field: e.target.value}))}
                    placeholder="Field in related table that references main table"
                    required
                  />
                  <div className="form-text">
                    Name of the field in the related table that contains references to your main table.
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">
                    <input
                      type="checkbox"
                      checked={formData.one_to_one}
                      onChange={(e) => setFormData(prev => ({...prev, one_to_one: e.target.checked}))}
                    />
                    One-to-One Relationship
                  </label>
                  <div className="form-text">
                    Check if each main record has at most one related record.
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">Flatten Mode *</label>
                  <select
                    className="form-control"
                    value={formData.flatten_mode}
                    onChange={(e) => setFormData(prev => ({...prev, flatten_mode: e.target.value}))}
                    required
                  >
                    <option value="first">First Record Only</option>
                    <option value="concat">Concatenate Values</option>
                    <option value="scripted">Custom Script</option>
                  </select>
                  <div className="form-text">
                    How to handle multiple related records:
                    <br />• <strong>First:</strong> Use only the first related record
                    <br />• <strong>Concat:</strong> Join all values with commas
                    <br />• <strong>Scripted:</strong> Use custom logic to combine records
                  </div>
                </div>

                {formData.flatten_mode === 'scripted' && (
                  <div className="form-group">
                    <label className="form-label">Custom Flatten Script *</label>
                    <textarea
                      className="form-control"
                      value={formData.script}
                      onChange={(e) => setFormData(prev => ({...prev, script: e.target.value}))}
                      rows="6"
                      placeholder="// Process related records array
// Available: relatedRecords, mainRecordId, alias
return relatedRecords.map(r => r.name).join(', ');"
                      required
                    />
                    <div className="form-text">
                      JavaScript to process the array of related records. Must return a string value.
                    </div>
                  </div>
                )}

                {errors.submit && (
                  <div className="error-message">
                    {errors.submit}
                  </div>
                )}
              </div>

              <div className="modal-footer">
                <button type="button" onClick={() => setShowForm(false)} className="btn btn-outline">
                  Cancel
                </button>
                <button type="submit" className="btn btn-success">
                  {editingSource ? 'Update Source' : 'Add Source'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}","import React, { useState, useMemo } from 'react';
import { ExportConfigService } from '../services/ExportConfigService.js';

export default function ExportTester({ definition, onBack, onDefinitionSelect, definitions }) {
  const configService = useMemo(() => new ExportConfigService(), []);
  const [testing, setTesting] = useState(false);
  const [testResults, setTestResults] = useState(null);
  const [error, setError] = useState(null);
  const [recordIds, setRecordIds] = useState('');

  const selectedDefinition = definition || definitions[0];

  const handleTestExport = async () => {
    if (!selectedDefinition) {
      setError('Please select an export definition to test');
      return;
    }

    try {
      setTesting(true);
      setError(null);
      setTestResults(null);

      const definitionId = configService.extractValue(selectedDefinition.sys_id);
      const ids = recordIds.trim() ? recordIds.split(',').map(id => id.trim()) : [];

      const results = await configService.testExport(definitionId, ids, true);
      setTestResults(results);

      if (!results.success) {
        setError(results.error || 'Export test failed');
      }
    } catch (err) {
      setError('Failed to test export: ' + err.message);
    } finally {
      setTesting(false);
    }
  };

  const handleDownloadSample = () => {
    if (!testResults?.csvContent) return;

    const blob = new Blob([testResults.csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${configService.extractDisplayValue(selectedDefinition.export_name)}_sample.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
  };

  const parseCSVForPreview = (csvContent) => {
    if (!csvContent) return { headers: [], rows: [] };

    const lines = csvContent.trim().split('\n');
    if (lines.length === 0) return { headers: [], rows: [] };

    const headers = lines[0].split(configService.extractValue(selectedDefinition.delimiter) === 'semicolon' ? ';' : ',')
      .map(header => header.replace(/^"|"$/g, ''));

    const rows = lines.slice(1, 11).map(line => 
      line.split(configService.extractValue(selectedDefinition.delimiter) === 'semicolon' ? ';' : ',')
        .map(cell => cell.replace(/^"|"$/g, ''))
    );

    return { headers, rows };
  };

  if (!selectedDefinition) {
    return (
      <div className="export-tester">
        <div className="manager-header">
          <button onClick={onBack} className="btn btn-outline">← Back to Console</button>
          <h2>Export Tester</h2>
        </div>
        <div className="empty-state">
          <p>Please select an export definition to test.</p>
        </div>
      </div>
    );
  }

  const previewData = testResults?.previewContent ? parseCSVForPreview(testResults.previewContent) : null;

  return (
    <div className="export-tester">
      <div className="manager-header">
        <button onClick={onBack} className="btn btn-outline">← Back to Console</button>
        <h2>Export Tester</h2>

        {definitions.length > 1 && (
          <div className="definition-selector">
            <label>Export Definition:</label>
            <select
              value={configService.extractValue(selectedDefinition.sys_id)}
              onChange={(e) => {
                const selected = definitions.find(d => 
                  configService.extractValue(d.sys_id) === e.target.value
                );
                onDefinitionSelect(selected);
                setTestResults(null);
                setError(null);
              }}
              className="form-control"
            >
              {definitions.map(def => (
                <option key={configService.extractValue(def.sys_id)} value={configService.extractValue(def.sys_id)}>
                  {configService.extractDisplayValue(def.export_name)}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      <div className="tester-content">
        <div className="test-section">
          <h3>Test Export: {configService.extractDisplayValue(selectedDefinition.export_name)}</h3>

          <div className="export-info">
            <div className="info-grid">
              <div className="info-item">
                <label>Target Table:</label>
                <span>{configService.extractDisplayValue(selectedDefinition.target_table)}</span>
              </div>
              <div className="info-item">
                <label>Delimiter:</label>
                <span>{configService.extractValue(selectedDefinition.delimiter) === 'comma' ? 'Comma (,)' : 'Semicolon (;)'}</span>
              </div>
              <div className="info-item">
                <label>Status:</label>
                <span className={String(selectedDefinition.active) === 'true' ? 'status-active' : 'status-inactive'}>
                  {String(selectedDefinition.active) === 'true' ? 'Active' : 'Inactive'}
                </span>
              </div>
            </div>
          </div>

          <div className="test-controls">
            <div className="form-group">
              <label className="form-label">Test Record IDs (Optional)</label>
              <textarea
                className="form-control"
                value={recordIds}
                onChange={(e) => setRecordIds(e.target.value)}
                rows="3"
                placeholder="Enter specific record sys_ids to test (comma-separated)
Leave empty to use filtered records from the export definition"
              />
              <div className="form-text">
                If provided, the export will test only these specific records. 
                Otherwise, it will use the export definition's query and filter settings.
              </div>
            </div>

            <div className="test-actions">
              <button 
                onClick={handleTestExport}
                className="btn btn-primary btn-lg"
                disabled={testing}
              >
                {testing ? 'Generating Preview...' : 'Generate Preview'}
              </button>
            </div>
          </div>
        </div>

        {error && (
          <div className="error-section">
            <div className="error-message">
              <h4>Export Test Failed</h4>
              <p>{error}</p>
            </div>
          </div>
        )}

        {testResults && testResults.success && (
          <div className="results-section">
            <div className="results-header">
              <h4>Export Preview Results</h4>
              <div className="results-stats">
                <span className="stat">
                  <strong>{testResults.processedCount || 0}</strong> records processed
                </span>
                {testResults.totalLines && (
                  <span className="stat">
                    <strong>{testResults.totalLines}</strong> total rows
                  </span>
                )}
                <button 
                  onClick={handleDownloadSample}
                  className="btn btn-success btn-sm"
                  disabled={!testResults.csvContent}
                >
                  Download Sample CSV
                </button>
              </div>
            </div>

            {previewData && (
              <div className="preview-section">
                <h5>Preview (First 10 Rows)</h5>
                <div className="preview-table-container">
                  <table className="preview-table">
                    <thead>
                      <tr>
                        {previewData.headers.map((header, index) => (
                          <th key={index}>{header}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {previewData.rows.map((row, index) => (
                        <tr key={index}>
                          {row.map((cell, cellIndex) => (
                            <td key={cellIndex} title={cell}>
                              {cell.length > 50 ? cell.substring(0, 50) + '...' : cell}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {previewData.rows.length === 0 && (
                  <div className="no-data">
                    <p>No data rows found. This could mean:</p>
                    <ul>
                      <li>The export query returned no records</li>
                      <li>All records were filtered out by the filter script</li>
                      <li>No field mappings are configured</li>
                    </ul>
                  </div>
                )}
              </div>
            )}

            {testResults.errors && testResults.errors.length > 0 && (
              <div className="warnings-section">
                <h5>Warnings & Issues</h5>
                <ul className="error-list">
                  {testResults.errors.map((error, index) => (
                    <li key={index} className="warning-item">
                      {error}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}

        {!testResults && !error && (
          <div className="instructions-section">
            <h4>Testing Instructions</h4>
            <div className="instructions">
              <div className="instruction-item">
                <div className="step-number">1</div>
                <div className="step-content">
                  <h5>Optional: Specify Test Records</h5>
                  <p>
                    Enter specific record sys_ids to test with, or leave empty to use the export definition's 
                    configured query and filters.
                  </p>
                </div>
              </div>

              <div className="instruction-item">
                <div className="step-number">2</div>
                <div className="step-content">
                  <h5>Generate Preview</h5>
                  <p>
                    Click "Generate Preview" to run the export engine and see the first 10 rows of output. 
                    This will validate your configuration without creating large files.
                  </p>
                </div>
              </div>

              <div className="instruction-item">
                <div className="step-number">3</div>
                <div className="step-content">
                  <h5>Review & Download</h5>
                  <p>
                    Examine the preview table to ensure headers and data appear as expected. 
                    Download a sample CSV file to test with external applications.
                  </p>
                </div>
              </div>
            </div>

            <div className="prerequisites">
              <h5>Prerequisites for Testing</h5>
              <ul>
                <li>Export definition must be configured with a target table</li>
                <li>At least one field mapping must be defined</li>
                <li>Target table must contain data to export</li>
                <li>Any referenced related sources must be properly configured</li>
              </ul>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}","/* Console Landing Styles */
.console-landing {
  display: flex;
  flex-direction: column;
  gap: 30px;
}

.landing-header {
  background: white;
  border-radius: 8px;
  padding: 20px;
