@media (max-width: 768px) {
  .header-content {
    flex-direction: column;
    align-items: stretch;
    gap: 15px;
  }

  .console-nav {
    justify-content: center;
    flex-wrap: wrap;
  }

  .console-content {
    padding: 20px 15px;
  }

  .btn {
    padding: 8px 16px;
    font-size: 0.85rem;
  }
