    }
  };

  const navigateTo = (view, definition = null) => {
    setCurrentView(view);
    setSelectedDefinition(definition);
    setError(null);
  };

  const handleDefinitionCreated = (newDefinition) => {
    setDefinitions(prev => [...prev, newDefinition]);
    setSelectedDefinition(newDefinition);
    setCurrentView('field-mapping');
  };

  const handleDefinitionUpdated = (updatedDefinition) => {
    setDefinitions(prev => prev.map(def => 
      configService.extractValue(def.sys_id) === configService.extractValue(updatedDefinition.sys_id) 
        ? updatedDefinition 
        : def
    ));
    if (selectedDefinition) {
      setSelectedDefinition(updatedDefinition);
    }
  };

  const handleDefinitionDeleted = (deletedId) => {
    setDefinitions(prev => prev.filter(def => 
      configService.extractValue(def.sys_id) !== deletedId
    ));
    if (selectedDefinition && configService.extractValue(selectedDefinition.sys_id) === deletedId) {
      setSelectedDefinition(null);
      setCurrentView('landing');
    }
  };

  const renderCurrentView = () => {
    switch (currentView) {
      case 'landing':
        return (
          <ConsoleLanding
            definitions={definitions}
            loading={loading}
            onCreateNew={() => navigateTo('create-wizard')}
            onEditDefinition={(def) => navigateTo('create-wizard', def)}
            onManageMapping={(def) => navigateTo('field-mapping', def)}
            onManageRelated={(def) => navigateTo('related-sources', def)}
            onTestExport={(def) => navigateTo('test-export', def)}
            onDeleteDefinition={handleDefinitionDeleted}
            onRefresh={loadDefinitions}
          />
        );

      case 'create-wizard':
        return (
          <ExportDefinitionWizard
            definition={selectedDefinition}
            onCancel={() => navigateTo('landing')}
            onComplete={handleDefinitionCreated}
            onUpdate={handleDefinitionUpdated}
          />
        );

      case 'field-mapping':
        return (
          <FieldMappingManager
            definition={selectedDefinition}
            onBack={() => navigateTo('landing')}
            onDefinitionSelect={(def) => navigateTo('field-mapping', def)}
            definitions={definitions}
          />
        );

      case 'related-sources':
        return (
          <RelatedSourceManager
            definition={selectedDefinition}
            onBack={() => navigateTo('landing')}
            onDefinitionSelect={(def) => navigateTo('related-sources', def)}
            definitions={definitions}
          />
        );

      case 'test-export':
        return (
          <ExportTester
            definition={selectedDefinition}
            onBack={() => navigateTo('landing')}
            onDefinitionSelect={(def) => navigateTo('test-export', def)}
            definitions={definitions}
          />
        );

      default:
        return (
          <div className="error-view">
            <h2>Unknown View</h2>
            <button onClick={() => navigateTo('landing')} className="btn btn-primary">
              Return to Home
            </button>
          </div>
        );
    }
  };

  return (
    <div className="export-console">
      <header className="console-header">
        <div className="header-content">
          <h1>CSV Export Configuration Console</h1>
          <nav className="console-nav">
            <button 
              onClick={() => navigateTo('landing')} 
              className={currentView === 'landing' ? 'nav-btn active' : 'nav-btn'}
            >
              Home
            </button>
            {selectedDefinition && (
              <>
                <button 
                  onClick={() => navigateTo('field-mapping', selectedDefinition)} 
                  className={currentView === 'field-mapping' ? 'nav-btn active' : 'nav-btn'}
                >
                  Field Mapping
                </button>
                <button 
                  onClick={() => navigateTo('related-sources', selectedDefinition)} 
                  className={currentView === 'related-sources' ? 'nav-btn active' : 'nav-btn'}
                >
                  Related Sources
                </button>
                <button 
                  onClick={() => navigateTo('test-export', selectedDefinition)} 
                  className={currentView === 'test-export' ? 'nav-btn active' : 'nav-btn'}
                >
                  Test Export
                </button>
              </>
            )}
          </nav>
        </div>
      </header>

      <main className="console-content">
        {error && (
          <div className="error-banner">
            <div className="error-content">
              <span className="error-text">{error}</span>
              <button onClick={() => setError(null)} className="error-close">×</button>
            </div>
          </div>
        )}

        {renderCurrentView()}
      </main>
    </div>
  );
}"],"names":["ExportConfigService","extractValue","field","value","extractDisplayValue","display_value","getExportDefinitions","_fetchTableData","tables","exportDefinition","sysparm_display_value","sysparm_order_by","getExportDefinition","sysId","data","sysparm_query","length","createExportDefinition","definitionData","_postTableData","updateExportDefinition","_putTableData","deleteExportDefinition","_deleteTableData","getFieldMappings","definitionId","exportMapping","createFieldMapping","mappingData","updateFieldMapping","deleteFieldMapping","getRelatedSources","csvRelatedSource","createRelatedSource","sourceData","updateRelatedSource","deleteRelatedSource","testExport","recordIds","previewOnly","response","fetch","method","headers","window","g_ck","body","JSON","stringify","name","script","ok","Error","status","statusText","json","parse","result","error","console","message","getTableList","sysparm_fields","sysparm_limit","map","table","label","getTableFields","tableName","fields","element","column_label","type","internal_type","maxLength","max_length","reference","validateExportDefinition","errors","export_name","trim","push","target_table","batch_size","isNaN","attachment_mode","attachment_table","attachment_record_id","validateFieldMapping","header_label","source_type","source_field","source_table_alias","script_field","order_number","validateRelatedSource","existingAliases","alias","includes","relationship_field","flatten_mode","params","searchParams","URLSearchParams","toString","errorMessage","errorData","e","constructor","scopeName","exportLog","ConsoleLanding","definitions","loading","onCreateNew","onEditDefinition","onManageMapping","onManageRelated","onTestExport","onDeleteDefinition","onRefresh","configService","stats","useMemo","total","active","filter","def","String","inactive","handleDelete","definition","defName","confirm","sys_id","alert","_jsxs","div","className","_jsx","children","button","onClick","h2","h3","p","targetTable","isActive","lastModif